export function getAnswer(item: InterviewQuestion): InterviewAnswer {
  const rule = rules.find((candidate) => candidate.match.test(item.question));
  const fallback = categoryDefaults[item.category] ?? categoryDefaults["Инженерные и поведенческие"];

  if (!rule) return fallback;

  return {
    short: rule.short,
    points: rule.points?.length ? rule.points : fallback.points,
    example: rule.example ?? fallback.example,
    caveat: rule.caveat ?? fallback.caveat,
  };
}
